<script>
  function fitSlides() {
    var maxW = window.innerWidth - 64;
    var maxH = window.innerHeight - 64;
    var scale = Math.min(maxW / 1920, maxH / 1080, 1);
    document.querySelectorAll('.frame').forEach(function (frame) {
      frame.style.width = (1920 * scale) + 'px';
      frame.style.height = (1080 * scale) + 'px';
      frame.querySelector('.slide').style.transform = 'scale(' + scale + ')';
    });
  }
  window.addEventListener('resize', fitSlides);
